import { CodeBlock, Pre } from 'fumadocs-ui/components/codeblock';
import {
  ImageZoom,
  type ImageZoomProps,
} from 'fumadocs-ui/components/image-zoom';
import defaultMdxComponents from 'fumadocs-ui/mdx';
import * as Twoslash from 'fumadocs-twoslash/ui';
import {
  DocsBody as PostsBody,
  DocsDescription as PostsDescription,
  DocsPage as PostsPage,
  DocsTitle as PostsTitle,
} from 'fumadocs-ui/page';
import type { Metadata } from 'next';
import { Mermaid } from '@/components/mermaid';
import { notFound } from 'next/navigation';
import { title as homeTitle } from '@/app/layout.config';
import { PostJsonLd } from '@/components/json-ld';
import { LinkPreview } from '@/components/link-preview';
import { TagCard } from '@/components/tag-card';
import { getPost, getPosts } from '@/lib/source';
import { Comments } from '@/components/comments';  // ← 添加这行

export const dynamicParams = false;

const Page = async (props: PageProps<'/posts/[slug]'>) => {
  const params = await props.params;
  const post = getPost([params.slug]);

  if (post === undefined) {
    notFound();
  }

  const date = new Date(post.data.date).toLocaleDateString('zh-CN', {
    timeZone: 'Asia/Shanghai',
  });

  const tags = post.data.tags ?? [];

  const path = `content/${post.path}`;

  const MDX = post.data.body;

  return (
    <PostsPage
      toc={post.data.toc}
      full={post.data.full}
      tableOfContent={{
        style: 'clerk',
        single: false,
      }}
    >
      <p className='text-right'>{date}</p>
      <PostsTitle>{post.data.title}</PostsTitle>
      <PostsDescription className='mb-0'>
        {post.data.description}
      </PostsDescription>
      <div className='flex gap-2 flex-wrap mb-8'>
        {tags.map((tag) => (
          <TagCard name={tag} key={tag} />
        ))}
      </div>
      <PostsBody>
        <MDX
          components={{
            ...defaultMdxComponents,
            ...Twoslash,
            Mermaid,
            img: (props: ImageZoomProps) => <ImageZoom {...props} />,
            pre: ({ ...props }) => (
              <CodeBlock
                {...props}
                viewportProps={{
                  className: 'max-h-fit',
                }}
              >
                <Pre>{props.children}</Pre>
              </CodeBlock>
            ),
            LinkPreview,
          }}
        />
      </PostsBody>
      <div className="mt-16">        {/* ← 添加这行 */}
        <Comments />                  {/* ← 添加这行 */}
      </div>                          {/* ← 添加这行 */}
      <PostJsonLd post={post} />
    </PostsPage>
  );
};

export default Page;

export const generateStaticParams = () => {
  return getPosts().map((post) => ({
    slug: post.slugs[0],
  }));
};

export const generateMetadata = async (props: {
  params: Promise<{ slug: string }>;
}): Promise<Metadata> => {
  const params = await props.params;
  const post = getPost([params.slug]);
  if (post === undefined) return {};

  const title = post.data.title;
  const description = post.data.description;
  const imageParams = new URLSearchParams();
  imageParams.set('title', title);
  imageParams.set('description', description ?? '');

  return {
    metadataBase: new URL(
      process.env.NEXT_PUBLIC_SITE_URL ?? 'http://wangjb.appinn.me ',
    ),
    title,
    description,
    openGraph: {
      title,
      description,
      images: `/api/og?${imageParams}`,
      url: post.url,
      siteName: homeTitle,
    },
    twitter: {
      title,
      description,
      images: `/api/og?${imageParams}`,
    },
    alternates: {
      canonical: post.url,
      types: {
        'application/rss+xml': '/api/rss.xml',
      },
    },
  };
};
